starter_source:
CREATE OR REPLACE TABLE gold.fct_order_revenue AS
SELECT order_id, order_date, order_total - shipping_fee AS net_revenue
FROM source.shop_orders;

CREATE OR REPLACE VIEW gold.dim_customer_public AS
SELECT customer_id, customer_name, email, city, segment
FROM source.crm_customers;

{
  "name": "sales_star",
  "tables": [
    {
      "name": "gold.fct_sales",
      "role": "fact",
      "grain": [
        "order_id",
        "line_number"
      ]
    },
    {
      "name": "gold.dim_date",
      "role": "dimension",
      "key": "date_key",
      "unknown_member": -1
    },
    {
      "name": "gold.dim_customer",
      "role": "dimension",
      "key": "customer_key",
      "business_key": [
        "customer_id"
      ],
      "unknown_member": -1
    },
    {
      "name": "gold.dim_product",
      "role": "dimension",
      "key": "product_key",
      "business_key": [
        "product_id"
      ],
      "unknown_member": -1
    }
  ],
  "relationships": [
    {
      "from": "gold.fct_sales.order_date_key",
      "to": "gold.dim_date.date_key",
      "cardinality": "many-to-one",
      "cross_filter": "single",
      "active": true
    },
    {
      "from": "gold.fct_sales.ship_date_key",
      "to": "gold.dim_date.date_key",
      "cardinality": "many-to-one",
      "cross_filter": "single",
      "active": true
    },
    {
      "from": "gold.fct_sales.customer_id",
      "to": "gold.dim_customer.customer_id",
      "cardinality": "many-to-one",
      "cross_filter": "single",
      "active": true
    },
    {
      "from": "gold.fct_sales.product_key",
      "to": "gold.dim_product.product_key",
      "cardinality": "many-to-one",
      "cross_filter": "single",
      "active": true
    }
  ]
}

{
  "name": "account_fees",
  "tables": [
    {
      "name": "gold.fct_account_fees",
      "role": "fact",
      "grain": [
        "account_key",
        "month_start"
      ]
    },
    {
      "name": "gold.dim_customer",
      "role": "dimension",
      "key": "customer_key"
    },
    {
      "name": "gold.bridge_account_holder",
      "role": "fact",
      "grain": [
        "account_key",
        "customer_key"
      ]
    }
  ],
  "relationships": [
    {
      "from": "gold.fct_account_fees.account_key",
      "to": "gold.bridge_account_holder.account_key",
      "cardinality": "many-to-many",
      "cross_filter": "both",
      "active": true
    },
    {
      "from": "gold.bridge_account_holder.customer_key",
      "to": "gold.dim_customer.customer_key",
      "cardinality": "many-to-one",
      "cross_filter": "single",
      "active": true
    }
  ]
}
